    # Find the full-width horizontal divider.
    divider = next(
        (r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] == 2),
        None
    )
    if divider is None:
        return [row[:] for row in grid]

    bg = grid[0][0]
