           if grid[r][c] not in (bg, 2, 8)]
    if not obj:
        return [row[:] for row in grid]

    r0 = min(r for r, c in obj)
    r1 = max(r for r, c in obj)
    c0 = min(c for r, c in obj)
    c1 = max(c for r, c in obj)
    patch = [grid[r][c0:c1 + 1] for r in range(r0, r1 + 1)]
    ph, pw = len(patch), c1 - c0 + 1

    # Move the object to the divider-facing edge of its side.
    if r1 < divider:
        nr0 = divider - ph
        trail = nr0 - 1
    else:
        nr0 = divider + 1
        trail = nr0 + ph

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (2,):
                out[r][c] = bg

    for dr in range(ph):
        for dc in range(pw):
            out[nr0 + dr][c0 + dc] = patch[dr][dc]

    if 0 <= trail < h:
        out[trail] = [8] * w
    return out
